#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void matmul_kernel(const half* A, const half* B, half* C, int N) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < N && col < N) {
        half sum = __hzero();
        for (int k = 0; k < N; ++k) {
            sum = __hadd(sum, __hmul(A[row * N + k], B[k * N + col]));
        }
        C[row * N + col] = sum;
    }
}

extern "C" {
void launch_matmul(const half* A, const half* B, half* C, int N) {
    dim3 blockSize(16, 16);
    dim3 gridSize((N + blockSize.x - 1) / blockSize.x, 
                  (N + blockSize.y - 1) / blockSize.y);
    matmul_kernel<<<gridSize, blockSize>>>(A, B, C, N);
    cudaDeviceSynchronize();
}
}
